<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/_core/bootstrap.php';
require_once dirname(__DIR__).'/_core/new_user_invites.php';
$method=require_method('GET','POST');
if($method==='POST'){
    $input=json_input();$grant=$_SESSION['new_user_invitation']??null;
    if(!is_array($grant)||(int)($grant['expiresAt']??0)<=time())api_error('This invitation has expired. Ask an administrator for a new one.',410,'invitation_expired');
    if(!is_string($input['csrfToken']??null)||!is_string($grant['csrfToken']??null)||!hash_equals($grant['csrfToken'],$input['csrfToken']))api_error('The invitation form expired. Reload the scanned link.',403,'csrf_invalid');
    if(($input['password']??null)!==($input['confirmPassword']??null))api_error('Passwords do not match.',422,'password_mismatch');
    $account=array_intersect_key($input,array_flip(['firstName','lastName','preferredName','username','password']));
    $user=create_invited_user(db(),(int)$grant['adminUserId'],$account);unset($_SESSION['new_user_invitation']);json_response(['user'=>$user,'created'=>true],201);
}
$record=consume_new_user_token(db(),is_string($_GET['token']??null)?$_GET['token']:'');
if(!$record){http_response_code(410);header('Content-Type: text/html; charset=utf-8');echo '<!doctype html><meta name="viewport" content="width=device-width"><title>Invitation unavailable</title><p>This invitation is invalid, expired, or already used. Ask an administrator for a new one.</p>';exit;}
$csrf=bin2hex(random_bytes(32));$_SESSION['new_user_invitation']=['adminUserId'=>$record['adminUserId'],'expiresAt'=>time()+NEW_USER_TOKEN_TTL,'csrfToken'=>$csrf];
header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store');
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Profile</title><style>
:root{color-scheme:light;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:#001e60;color:#001e60}*{box-sizing:border-box}html{min-width:320px;background:#001e60}body{min-height:100dvh;margin:0;padding:clamp(16px,4vw,36px) 14px;display:grid;place-items:center;background:radial-gradient(circle at 50% 0,rgb(0 83 226 / 42%),transparent 42%),#001e60}.profile-card{width:min(100%,580px);overflow:hidden;border:1px solid rgb(169 221 247 / 82%);border-radius:18px;background:#a9ddf7;box-shadow:0 22px 60px rgb(0 0 0 / 38%)}.profile-header{padding:20px 28px 18px;text-align:center;background:linear-gradient(180deg,#46515c 0%,#2f3943 48%,#202933 100%);border-bottom:1px solid rgb(255 255 255 / 35%);color:#fff}.brand{margin:0 0 3px;color:#a9ddf7;font-size:13px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.profile-header h1{margin:0;font-size:clamp(28px,7vw,38px);line-height:1.1}.profile-header p{margin:7px 0 0;color:rgb(255 255 255 / 84%);font-size:15px}.profile-body{padding:20px clamp(18px,5vw,30px) 24px}fieldset{min-width:0;margin:0 0 18px;padding:0;border:0}legend{width:100%;margin:0 0 11px;padding:0 0 7px;border-bottom:1px solid rgb(0 30 96 / 30%);font-size:16px;font-weight:800}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px 14px}.field-grid .wide{grid-column:1/-1}label{min-width:0;display:grid;gap:6px;color:#001e60;font-size:14px;font-weight:750}.optional{font-size:12px;font-weight:600;opacity:.7}input{width:100%;min-width:0;height:46px;padding:10px 12px;border:2px solid transparent;border-radius:9px;outline:0;background:#fff;color:#001e60;font:inherit;font-size:16px;box-shadow:0 1px 2px rgb(0 30 96 / 15%);transition:border-color 140ms ease,box-shadow 140ms ease}input:hover{border-color:rgb(0 83 226 / 36%)}input:focus{border-color:#0053e2;box-shadow:0 0 0 3px rgb(0 83 226 / 20%)}input::placeholder{color:rgb(0 30 96 / 46%)}.form-note{margin:-5px 0 15px;color:rgb(0 30 96 / 76%);font-size:13px;line-height:1.4}#message{min-height:21px;margin:0 0 8px;padding:0;color:#7b1734;font-size:14px;font-weight:750;text-align:center}#message:empty{display:none}.submit-button,.open-button{width:100%;min-height:50px;display:grid;place-items:center;margin:0;padding:11px 18px;border:1px solid rgb(255 255 255 / 66%);border-radius:10px;background:#0053e2;color:#fff;font:inherit;font-size:17px;font-weight:800;text-decoration:none;box-shadow:0 5px 12px rgb(0 30 96 / 22%);cursor:pointer;transition:filter 140ms ease,transform 100ms ease}.submit-button:hover,.open-button:hover{filter:brightness(1.08)}.submit-button:active,.open-button:active{transform:translateY(1px)}.submit-button:disabled{cursor:wait;opacity:.72}.success{text-align:center}.success-mark{width:68px;height:68px;display:grid;place-items:center;margin:4px auto 15px;border-radius:50%;background:#0053e2;color:#fff;font-size:38px;font-weight:900}.success h2{margin:0 0 7px;font-size:28px}.success p{margin:0 0 20px;line-height:1.5}@media(max-width:520px){body{place-items:start center;padding:10px}.profile-card{border-radius:14px}.profile-header{padding:17px 18px 15px}.profile-body{padding:17px 16px 19px}.field-grid{grid-template-columns:1fr;gap:11px}.field-grid .wide{grid-column:auto}fieldset{margin-bottom:15px}}
</style></head><body><main class="profile-card"><header class="profile-header"><p class="brand">ClockTimer</p><h1>Create Your Profile</h1><p>Enter your details to finish setting up access.</p></header><form id="profile" class="profile-body"><fieldset><legend>Personal details</legend><div class="field-grid"><label>First name<input name="firstName" autocomplete="given-name" required maxlength="100" placeholder="First name"></label><label>Last name<input name="lastName" autocomplete="family-name" required maxlength="100" placeholder="Last name"></label><label class="wide">Preferred name <span class="optional">Optional</span><input name="preferredName" autocomplete="nickname" maxlength="100" placeholder="What should we call you?"></label></div></fieldset><fieldset><legend>Sign-in details</legend><div class="field-grid"><label class="wide">Username<input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" required maxlength="191" placeholder="Choose a username"></label><label>Password<input name="password" type="password" autocomplete="new-password" required maxlength="72" placeholder="Create a password"></label><label>Confirm password<input name="confirmPassword" type="password" autocomplete="new-password" required maxlength="72" placeholder="Enter it again"></label></div></fieldset><p class="form-note">This invitation can be used once. Your profile will be ready immediately after submission.</p><p id="message" role="alert" aria-live="polite"></p><button class="submit-button" type="submit">Create Profile</button></form></main><script>
const form=document.getElementById('profile'),message=document.getElementById('message'),button=form.querySelector('button');form.addEventListener('submit',async event=>{event.preventDefault();message.textContent='Creating your profile…';button.disabled=true;const body=Object.fromEntries(new FormData(form));body.csrfToken='<?=htmlspecialchars($csrf,ENT_QUOTES)?>';try{const response=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok){message.textContent=data.message||'Unable to create profile.';button.disabled=false;return;}form.className='profile-body success';form.innerHTML='<div class="success-mark" aria-hidden="true">✓</div><h2>Profile created</h2><p>Your account is ready. Open ClockTimer and sign in with your new username.</p><a class="open-button" href="/">Open ClockTimer</a>';}catch(error){message.textContent='Unable to connect. Check your connection and try again.';button.disabled=false;}});
